// Field names from the Week 7 tutorial (RAK7204). Change site to match your campus.
const s = msg.payload;
const o = s.object || {};
const fields = {};
if (typeof o.temperature_7 === 'number') fields.temperature = o.temperature_7;
if (typeof o.humidity_6    === 'number') fields.humidity    = o.humidity_6;
if (typeof o.barometer_8   === 'number') fields.pressure    = o.barometer_8;
if (Object.keys(fields).length === 0) { node.warn('no env fields'); return null; }
msg.measurement = 'cqu_environment';
msg.payload = [fields, { device: s.deviceInfo.deviceName, application: s.deviceInfo.applicationName, site: 'MEL' }];
return msg;

// EDIT thresholds after you have looked at your own data
const T = { humLow: 30, humHigh: 85, tempHigh: 35 };
const f = msg.payload[0], a = [];
if (f.humidity !== undefined && f.humidity < T.humLow)  a.push('Air humidity low: ' + f.humidity + ' %');
if (f.humidity !== undefined && f.humidity > T.humHigh) a.push('Air humidity high: ' + f.humidity + ' %');
if (f.temperature !== undefined && f.temperature > T.tempHigh) a.push('Air temperature high: ' + f.temperature + ' C');
if (!a.length) return null;
const last = context.get('last') || 0;
if (Date.now() - last < 3600000) return null;
context.set('last', Date.now());
msg.payload = { text: a.join('; '), time: new Date().toISOString() };
return msg;

// Field names from the Week 7 tutorial. Change site to match your campus.
const s = msg.payload;
const o = s.object || {};
const map = { battery:'Bat', air_temperature:'TempC_DS18B20', soil_moisture:'water_SOIL', soil_temperature:'temp_SOIL', soil_conductivity:'conduct_SOIL' };
const fields = {};
for (const [out, inp] of Object.entries(map)) {
    const v = Number(o[inp]);
    if (o[inp] !== undefined && isFinite(v)) fields[out] = v;
}
if (Object.keys(fields).length === 0) { node.warn('no soil fields'); return null; }
msg.measurement = 'cqu_soil';
msg.payload = [fields, { device: s.deviceInfo.deviceName, application: s.deviceInfo.applicationName, site: 'MEL' }];
return msg;

// EDIT thresholds after you have looked at your own data (check the unit of water_SOIL first)
const T = { soilLow: 20, soilHigh: 45, batteryLow: 3.4 };
const f = msg.payload[0], a = [];
if (f.soil_moisture !== undefined && f.soil_moisture < T.soilLow)  a.push('Soil too dry: ' + f.soil_moisture);
if (f.soil_moisture !== undefined && f.soil_moisture > T.soilHigh) a.push('Soil too wet: ' + f.soil_moisture);
if (f.battery !== undefined && f.battery < T.batteryLow) a.push('Sensor battery low: ' + f.battery);
if (!a.length) return null;
const last = context.get('last') || 0;
if (Date.now() - last < 3600000) return null;
context.set('last', Date.now());
msg.payload = { text: a.join('; '), time: new Date().toISOString() };
return msg;
